pragma solidity 0.8.30;

// Synthetic defensive controls; no funds, network dependencies or production deployment.
interface InertValidator {
    function validate() external view;
}

contract GuardedValue {
    bool private paused = true;
    uint256 public pausedValue;
    uint256 public freshValue;

    constructor() {
        require(block.chainid == 31337 && block.timestamp > 0, "synthetic local-only fixture");
    }

    modifier requireLive() {
        _liveCheck();
        _;
    }

    function changePaused(uint256 amount) external requireLive {
        pausedValue += amount;
    }

    function changeFresh(uint256 amount) external {
        _freshCheck(0, 0);
        freshValue += amount;
    }

    function _liveCheck() internal view {
        _nestedLiveCheck();
    }

    function _nestedLiveCheck() private view {
        require(!paused, "paused state must prohibit changes");
    }

    function _freshCheck(uint256 updatedAt, uint256 maxAge) internal view {
        require(block.timestamp - updatedAt <= maxAge, "stale input must prohibit changes");
    }

    // Uncalled structural negative controls: no external endpoint is provided or contacted.
    function externalReference(InertValidator supplied) external view {
        supplied.validate();
    }

    function virtualReference() external pure {
        _virtualCheck();
    }

    function _virtualCheck() internal pure virtual {
        require(true);
    }

    function boundedRecursion(uint256 count) external pure {
        _bounded(count % 2);
    }

    function _bounded(uint256 count) private pure {
        if (count > 0) _bounded(count - 1);
    }
}
"},"test/mmaudit_generated/MMAuditInvariant_Fresh.t.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;
import "../../src/GuardedValue.sol";

interface MMAuditVm {
    function deal(address account, uint256 balance) external;
    function prank(address caller) external;
}

abstract contract MMAuditLocalInvariantTest {
    MMAuditVm internal constant vm = MMAuditVm(
        address(uint160(uint256(keccak256("hevm cheat code"))))
    );
    address[] private mmauditTargetContracts;
    event log_named_uint(string key, uint256 value);

    function targetContract(address target) internal {
        mmauditTargetContracts.push(target);
    }

    function targetContracts() public view returns (address[] memory) {
        return mmauditTargetContracts;
    }

    function bound(uint256 value, uint256 minimum, uint256 maximum)
        internal pure returns (uint256)
    {
        require(minimum <= maximum, "invalid bound");
        if (value >= minimum && value <= maximum) return value;
        uint256 span = maximum - minimum;
        if (span == type(uint256).max) return value;
        return minimum + (value % (span + 1));
    }

    function assertEq(uint256 left, uint256 right, string memory reason)
        internal pure
    {
        require(left == right, reason);
    }

    function assertGe(uint256 left, uint256 right, string memory reason)
        internal pure
    {
        require(left >= right, reason);
    }

    function assertLe(uint256 left, uint256 right, string memory reason)
        internal pure
    {
        require(left <= right, reason);
    }
}

contract MMAuditHandler_Fresh is MMAuditLocalInvariantTest {
    address internal target_GuardedValue;

    constructor(address local_GuardedValue) {
        target_GuardedValue = local_GuardedValue;
    }


    uint256 public attempts_Exercise;

    function action_Exercise() external {
        attempts_Exercise += 1;
        address actor = 0x1000000000000000000000000000000000000001;
        vm.prank(actor);
        (bool success,) = target_GuardedValue.call{value: 0}(abi.encodeWithSignature("changeFresh(uint256)", uint256(1)));
        if (!success) return;
    }

}

contract MMAuditInvariant_Fresh is MMAuditLocalInvariantTest {
    MMAuditHandler_Fresh internal handler;
    address internal target_GuardedValue;

    function setUp() public {
        assertEq(block.chainid, 31337, "unexpected fork chain");
        target_GuardedValue = address(new GuardedValue());
        require(target_GuardedValue.code.length > 0, "local deployment failed");
        handler = new MMAuditHandler_Fresh(target_GuardedValue);
        targetContract(address(handler));
    }

    function invariant_Fresh() public view {
        if (handler.attempts_Exercise() == 0) return;
        (bool leftOk, bytes memory leftData) = target_GuardedValue.staticcall(abi.encodeWithSignature("freshValue()"));
        require(leftOk && leftData.length >= 32, "probe failed");
        uint256 leftValue = abi.decode(leftData, (uint256));
        assertEq(leftValue, 0, "invariant violated");
    }

}
"},"test/mmaudit_generated/MMAuditInvariant_Pause.t.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
